"""Pydantic schemas for LangGraph interview questions, evaluations, and API."""

from datetime import datetime
from typing import Literal

from pydantic import BaseModel, ConfigDict, Field

from app.modules.interview.calibration import (
    DEFAULT_EXPERIENCE_LEVEL,
    ExperienceLevel,
)


DEFAULT_MAX_QUESTIONS = 8
DEFAULT_MAX_FOLLOW_UPS = 1


class InterviewQuestion(BaseModel):
    """Structured interview question generated by the interview engine."""

    question_id: str
    topic: str
    difficulty: Literal["easy", "medium", "hard"] = "medium"
    question_text: str
    question_type: Literal["conceptual", "applied", "gap_probe", "follow_up"] = (
        "conceptual"
    )
    is_follow_up: bool = False


class AnswerEvaluation(BaseModel):
    """Internal structured evaluation of a candidate's answer."""

    model_config = ConfigDict(extra="ignore")

    correctness: float = Field(ge=0.0, le=1.0)
    relevance: float = Field(ge=0.0, le=1.0)
    completeness: float = Field(ge=0.0, le=1.0)

    strengths: list[str] = Field(default_factory=list)
    missing_concepts: list[str] = Field(default_factory=list)

    follow_up_needed: bool = False
    follow_up_reason: str | None = None


class StartInterviewRequest(BaseModel):
    """Request body to start a new AI interview from a saved resume analysis."""

    analysis_id: int = Field(gt=0)
    interview_type: Literal["technical", "hr"] = Field(default="technical")
    experience_level: ExperienceLevel = Field(default=DEFAULT_EXPERIENCE_LEVEL)
    starting_difficulty: Literal["easy", "medium", "hard"] | None = Field(default=None)
    progression_mode: Literal["adaptive", "mock"] = Field(default="adaptive")
    max_questions: int = Field(default=DEFAULT_MAX_QUESTIONS, ge=1, le=15)
    max_follow_ups: int = Field(default=DEFAULT_MAX_FOLLOW_UPS, ge=0, le=3)


class SubmitAnswerRequest(BaseModel):
    """Request body to submit an answer to the active interview question."""

    question_id: str = Field(min_length=1, max_length=64)
    answer: str = Field(min_length=1, max_length=10000)


class PublicInterviewQuestion(BaseModel):
    """Question payload exposed to the candidate (never includes criteria)."""

    question_id: str
    topic: str
    difficulty: str
    question_text: str
    question_type: str
    is_follow_up: bool


class PublicConversationTurn(BaseModel):
    """Persisted turn exposed in session state without internal scores."""

    question_id: str
    question_index: int
    is_follow_up: bool
    topic: str
    difficulty: str
    question_type: str
    question_text: str
    answer_text: str | None = None
    created_at: datetime
    answered_at: datetime | None = None


class InterviewSessionResponse(BaseModel):
    """Public interview session state returned to the React InterviewRoom."""

    session_id: str
    analysis_id: int
    target_role: str
    interview_type: Literal["technical", "hr"] = "technical"
    experience_level: ExperienceLevel = DEFAULT_EXPERIENCE_LEVEL
    starting_difficulty: Literal["easy", "medium", "hard"] = "medium"
    progression_mode: Literal["adaptive", "mock"] = "adaptive"
    status: Literal["in_progress", "completed"]
    question_index: int
    max_questions: int
    follow_up_count: int
    max_follow_ups: int
    current_question: PublicInterviewQuestion | None = None
    conversation_history: list[PublicConversationTurn] = Field(
        default_factory=list
    )
    started_at: datetime
    completed_at: datetime | None = None
